// Result from creating a crypto top-up.
//
// The price is locked at this response. Send exactly `expectedAmountToken` of
// `asset` to `depositAddress`; on confirmation, the balance is credited at
// `quotedPriceUsd` regardless of price drift inside the address TTL.
type CryptoTopupResult struct {
	// Internal top-up ID for tracking/polling.
	TopupID string `json:"topupId"`
	// HD-derived Ethereum address to send funds to.
	DepositAddress string `json:"depositAddress"`
	// Asset to send (ETH or USDC).
	Asset purserpb.CryptoAsset `json:"asset"`
	// Human-readable asset symbol ("ETH" | "USDC").
	AssetSymbol string `json:"assetSymbol"`
	// Echo of input amountCents, in cents of the tenant's presentment currency.
	ExpectedAmountCents int `json:"expectedAmountCents"`
	// When this deposit address expires (24 hours from creation).
	ExpiresAt time.Time `json:"expiresAt"`
	// Token base units to send (decimal string; wei for 18-decimal assets).
	ExpectedAmountBaseUnits string `json:"expectedAmountBaseUnits"`
	// Human-friendly decimal of expectedAmountBaseUnits, e.g. "0.01515".
	ExpectedAmountToken string `json:"expectedAmountToken"`
	// Locked USD price per 1 whole token, e.g. "3300.45".
	QuotedPriceUsd string `json:"quotedPriceUsd"`
	// Source of the price quote ("chainlink" | "one_to_one").
	QuoteSource string `json:"quoteSource"`
	// When the price was locked.
	QuotedAt time.Time `json:"quotedAt"`
	// Network the deposit address lives on ("ethereum" | "arbitrum" | "base").
	Network string `json:"network"`
	// Presentment amount and the EUR credit it converts to, locked with the quote.
	Conversion *purserpb.FxConversion `json:"conversion,omitempty"`
}

// Status of a crypto top-up (for polling).
//
// `status` cycles: pending → confirming → completed (or expired).
type CryptoTopupStatus struct {
	// Top-up ID.
	ID string `json:"id"`
	// Deposit address.
	DepositAddress string `json:"depositAddress"`
	// Asset being received.
	Asset purserpb.CryptoAsset `json:"asset"`
	// Current status: pending, confirming, completed, expired.
	Status string `json:"status"`
	// Blockchain transaction hash (when detected).
	TxHash *string `json:"txHash,omitempty"`
	// Number of block confirmations.
	Confirmations int `json:"confirmations"`
	// Amount received in token base units (decimal string).
	ReceivedAmountBaseUnits *string `json:"receivedAmountBaseUnits,omitempty"`
	// Human-friendly decimal of receivedAmountBaseUnits.
	ReceivedAmountToken *string `json:"receivedAmountToken,omitempty"`
	// Amount credited to balance in `creditedAmountCurrency` cents.
	CreditedAmountCents *int `json:"creditedAmountCents,omitempty"`
	// Ledger currency of the credit, EUR.
	CreditedAmountCurrency *string `json:"creditedAmountCurrency,omitempty"`
	// Source of the locked price quote ("chainlink" | "one_to_one").
	QuoteSource *string `json:"quoteSource,omitempty"`
	// Network the deposit address lives on.
	Network *string `json:"network,omitempty"`
	// When the deposit address expires.
	ExpiresAt time.Time `json:"expiresAt"`
	// When payment was first detected on-chain.
	DetectedAt *time.Time `json:"detectedAt,omitempty"`
	// When balance was credited.
	CompletedAt *time.Time `json:"completedAt,omitempty"`
	// Presentment amount and the EUR credit it converts to, locked with the quote.
	Conversion *purserpb.FxConversion `json:"conversion,omitempty"`
}

// Verification + certificate lifecycle for a tenant's BYO domain. Returned by
// Navigator's GetCustomDomainStatus and surfaced verbatim so the dashboard can
// guide the operator through the manual DNS setup.
type CustomDomainStatus struct {
	// The domain Navigator is tracking (mirrors Tenant.customDomain).
	Domain string `json:"domain"`
	// pending_verification | verified | pending_alias | cert_issuing | cert_issued |
	// cert_failed | verification_failed | tearing_down — verbatim from Navigator.
	// pending_alias means the CNAMEs are verified and the domain waits for the tenant
	// alias certificate. verification_failed means the CNAMEs were not verified
	// within the fixed verification period.
	State string `json:"state"`
	// CNAME the operator points their public hostname at so the platform's TLS
	// ingress receives traffic.
	RequiredTrafficCname *string `json:"requiredTrafficCname,omitempty"`
	// CNAME the operator points `_acme-challenge.<their-domain>` at so Navigator
	// can complete DNS-01 issuance via the `acme-dns.<root>` delegated subzone.
	RequiredAcmeChallengeCname *string `json:"requiredAcmeChallengeCname,omitempty"`
	// Wall-clock UTC of the last successful verification check (null when never).
	LastVerifiedAt *time.Time `json:"lastVerifiedAt,omitempty"`
	// Wall-clock UTC of the most recent successful cert issuance (null when never).
	CertIssuedAt *time.Time `json:"certIssuedAt,omitempty"`
	// Wall-clock UTC of the current cert's expiry (null when no cert).
	CertExpiresAt *time.Time `json:"certExpiresAt,omitempty"`
	// Most recent error from verification / issuance, null when clean.
	LastError *string `json:"lastError,omitempty"`
}

// A single chapter view of a DVR recording. playbackId is the
// Commodore-minted public key for the chapter's VOD-shaped artifact;
// chapter playback uses the same artifact playback path as any VOD
// (not dvr+).
type DVRChapter struct {
	ChapterID string          `json:"chapterId"`
	State     DVRChapterState `json:"state"`
	// Public playback key minted by Commodore; null until finalization dispatches.
	PlaybackID   *string `json:"playbackId,omitempty"`
	IsCurrent    bool    `json:"isCurrent"`
	HasGaps      bool    `json:"hasGaps"`
	SegmentCount int     `json:"segmentCount"`
	// Absolute Unix epoch ms of the playable MKV span start; falls back to the scheduled chapter start before finalization.
	WallClockStartUnixMs float64 `json:"wallClockStartUnixMs"`
	// Absolute Unix epoch ms of the playable MKV span end; falls back to the scheduled chapter end before finalization.
	WallClockEndUnixMs float64 `json:"wallClockEndUnixMs"`
	// True when state ∈ {FINALIZED, FROZEN, RECLAIMED}.
	PlayableNow bool `json:"playableNow"`
	// Last finalization failure message (operator-facing); null on success or in-progress.
	LastFailureReason *string `json:"lastFailureReason,omitempty"`
}

// A reference to a chapter for the chapter list UI. Same shape as
